<script setup lang="ts">
import {ref, computed} from 'vue'

const props = defineProps<{
  modelValue: boolean,
  product: {
    name: string,
    price: string,
    currency: string,
    primaryImg: string
  },

  title: string,
  unitPriceTitle: string,
  selectQuantityTitle: string,
  totalPriceTitle: string,
  addToCardTitle: string,
  icon: string,
  variant: "outlined" | "plain" | "text" | "tonal" | "flat",
  rounded: boolean,
  color: string
}>()

const emit = defineEmits(['update:modelValue', 'confirm'])

const quantity = ref(1)

const close = () => {
  quantity.value = 1
  emit('update:modelValue', false)
}

function onDialogModel(v: boolean) {
  emit('update:modelValue', v)
  if (!v) quantity.value = 1
}

// Handle purchase
const handlePurchase = () => {
  emit('confirm', {
    quantity: quantity.value,
    total: (parseFloat(props.product.price) * quantity.value).toFixed(2)
  })
  close()
}

const totalPrice = computed(() => {
  return (parseFloat(props.product.price) * quantity.value).toFixed(2)
})
</script>

<template>
  <v-dialog :model-value="modelValue" @update:model-value="onDialogModel" max-width="450" scroll-strategy="none">
    <v-card class="rounded-xl pa-4">
      <v-card-title class="d-flex align-center">
        <span class="text-h5 font-weight-black">{{title}}</span>
        <v-spacer/>
        <v-btn icon="mdi-close" variant="text" @click="close"/>
      </v-card-title>

      <v-card-text>
        <div class="d-flex align-center mb-6">
          <v-avatar size="80" rounded="lg" class="mr-4 border">
            <v-img :src="product.primaryImg" cover/>
          </v-avatar>
          <div>
            <div class="text-subtitle-1 font-weight-bold">{{ product.name }}</div>
            <div class="text-body-2 text-grey">{{unitPriceTitle}} {{ product.currency }}{{ product.price }}</div>
          </div>
        </div>

        <div class="text-subtitle-2 mb-2">{{selectQuantityTitle}}</div>
        <div class="d-flex align-center mb-6">
          <v-btn
              icon="mdi-minus"
              variant="tonal"
              :color="color"
              size="small"
              :disabled="quantity <= 1"
              @click="quantity--"
          />
          <div class="mx-6 text-h6 font-weight-bold">{{ quantity }}</div>
          <v-btn
              icon="mdi-plus"
              variant="tonal"
              :color="color"
              size="small"
              @click="quantity++"
          />
          <v-spacer/>
          <div class="text-right">
            <div class="text-caption text-grey">{{totalPriceTitle}}</div>
            <div class="text-h6 font-weight-black" :style="{ color: 'var(--v-theme-success)' }">
              {{ product.currency }} {{ totalPrice }}
            </div>
          </div>
        </div>
      </v-card-text>

      <v-card-actions>
        <v-btn
            block
            size="x-large"
            :color="color"
            :variant="variant"
            class="font-weight-bold rounded-lg"
            @click="handlePurchase"
        >
          {{ addToCardTitle }}
        </v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>